<?php require __DIR__.'/includes/bootstrap.php';$q=trim($_GET['q']??'');$items=[];if($q!==''){$s=db()->prepare('SELECT id,name,price,image_url FROM products WHERE is_active=1 AND name LIKE ? ORDER BY id DESC LIMIT 40');$s->execute(['%'.$q.'%']);$items=$s->fetchAll();}?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>البحث</title><link rel="stylesheet" href="assets/css/store.css"></head><body><?php include __DIR__.'/includes/nav.php';?><main class="inner"><h1>البحث عن المنتجات</h1><form><input name="q" value="<?=h($q)?>" placeholder="اكتب اسم المنتج"><button class="gold">بحث</button></form><div class="grid"><?php foreach($items as $p):?><article><a href="product.php?id=<?=$p['id']?>"><img src="<?=h($p['image_url'])?>" alt=""><h3><?=h($p['name'])?></h3></a><strong><?=money($p['price'])?></strong></article><?php endforeach?></div></main><?php include __DIR__.'/includes/footer.php';?></body></html>